import { Divider, IconButton, Stack } from '@mui/material';
import { GithubLogo, GoogleLogo, TwitterLogo } from 'phosphor-react';
import React, { useEffect } from 'react'
import { LoginUser, RegisterUser } from '../../redux/slices/auth';
import { useDispatch } from 'react-redux';

const GoogleLogin = ({ actionType }) => {

    const dispatch = useDispatch();

    const handleCredentialResponse = (response) => {
        if (actionType === "Login") {
            dispatch(LoginUser({ ...response, auth_type: "GOOGLE", actionType }));
        } else if (actionType === "Register") {
            dispatch(RegisterUser({ ...response, auth_type: "GOOGLE", actionType }));
        }
    };

    useEffect(() => {

        const signin = () => {
            window.google.accounts.id.initialize({
                client_id: "396305485425-mpcokgsdtmj2btjntgh7hp1p1cbbu6po.apps.googleusercontent.com",
                context: "signup",
                callback: handleCredentialResponse,
                // auto_prompt: true,
                ux_mode: "popup",
                itp_support: true,
                auto_select: true,
            });

            // window.google.accounts.id.prompt();

            const buttonDiv = document.getElementById("buttonDiv");
            if (buttonDiv) {
                window.google.accounts.id.renderButton(
                    buttonDiv,
                    {
                        type: "icon",
                        shape: "circle",
                        theme: "outline",
                        size: "large",
                        text: "signin_with"
                    }  // customization attributes
                );
            }
        };
        signin();

    }, [])


    return (
        <div id="buttonDiv" >
        </div>
    );
};

const AuthSocial = ({ actionType }) => {
    return (
        <Stack direction={'column'}>
            <Divider sx={{
                my: 2.5, typography: "overline", color: "text.disabled", '&::before,::after': {
                    borderTopStyle: "dashed"
                }
            }}>
                OR
            </Divider>
            <Stack direction={'row'} alignItems={'center'} justifyContent={'center'} spacing={3}>
                <IconButton >
                    <GoogleLogin actionType={actionType} />
                </IconButton>
                <IconButton sx={{
                    border: '#dbd9d9',
                    '&:hover': {
                        borderColor: '#d4e3fc'
                    }
                }}>
                    <GithubLogo style={{
                        padding: 6.2,
                        border: "1px solid",
                        borderColor: 'inherit',
                        boxSizing: 'content-box',
                        borderRadius: "50px",
                    }}
                        size={25} />
                </IconButton>
                <IconButton sx={{
                    border: '#dbd9d9',
                    '&:hover': {
                        borderColor: '#d4e3fc'
                    }
                }}>
                    <TwitterLogo size={25}
                        style={{
                            padding: 6.2,
                            border: "1px solid",
                            borderColor: 'inherit',
                            boxSizing: 'content-box',
                            borderRadius: "50px",
                        }}
                        color='#1C9CEA'
                    />
                </IconButton>
            </Stack>
        </Stack>
    )
}

export default AuthSocial;